{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Ensure Google compute firewall ingress does not allow unrestricted http port 80 access",
      "resource": "google_compute_firewall.allow_http",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows unrestricted access (0.0.0.0/0) to HTTP (port 80), which exposes the service to the entire internet. This increases the risk of unauthorized access or attacks."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http\" {\n  name    = \"digital-library-content-management-platform-firewall-http\"\n  network = google_compute_network.digital_library_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n  source_ranges = [\"192.168.0.0/16\"] # Restrict access to a specific IP range\n  target_tags   = [\"http-server\"]\n}",
  "fix_summary": "Restricted the source_ranges from 0.0.0.0/0 to 192.168.0.0/16 to limit access to a specific IP range, reducing the risk of unauthorized access."
}
